package dev.pixel.voice;
import android.app.*;import android.os.*;import android.widget.*;import java.io.*;import java.net.URL;import javax.net.ssl.*;import org.json.*;import java.util.concurrent.*;
public final class ConversationModeActivity extends Activity {
 final ExecutorService io=Executors.newSingleThreadExecutor();EditText title,notes;TextView state,book;boolean loading=false,showArchive=false;Button archiveButton;String meetingId="";
 public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout page=new LinearLayout(this);page.setOrientation(1);int p=(int)(20*getResources().getDisplayMetrics().density);page.setPadding(p,p*2,p,p);ScrollView scroll=new ScrollView(this);scroll.addView(page);setContentView(scroll);TextView heading=new TextView(this);heading.setText("Conversation notes");heading.setTextSize(27);page.addView(heading);TextView intro=new TextView(this);intro.setText("GPT-6.1 Sol · Low · UltraFast\nPrepared notes and one saved notebook. No app actions or lookups. Say Start Work to explicitly hand off agreed action items to the configured Codex destination. Work never starts automatically. Results and verification are saved in the notebook. Use Conversation mode in the main three-dot menu to switch and reconnect.");page.addView(intro);state=new TextView(this);page.addView(state);title=new EditText(this);title.setHint("Meeting title");title.setSingleLine(true);page.addView(title);notes=new EditText(this);notes.setHint("Prepared notes and general project context");notes.setMinLines(6);notes.setGravity(48);page.addView(notes);Button prepare=new Button(this);prepare.setText("Save prepared notes");prepare.setOnClickListener(v->{try{request(new JSONObject().put("action","prepare").put("title",title.getText().toString()).put("notes",notes.getText().toString()));}catch(Exception e){}});page.addView(prepare);Button work=new Button(this);work.setText("Start agreed work");work.setOnClickListener(v->{if(meetingId.isEmpty())return;new AlertDialog.Builder(this).setTitle("Start agreed work?").setMessage("Submit this conversation’s agreed action items to the configured cloud VM or Codex Cloud environment. Ending a call alone never starts work.").setNegativeButton("Cancel",null).setPositiveButton("Start work",(d,w)->{try{request(new JSONObject().put("action","start_work").put("meetingId",meetingId).put("authorized",true).put("key",java.util.UUID.randomUUID().toString()));}catch(Exception e){}}).show();});page.addView(work);Button refresh=new Button(this);refresh.setText("Refresh notebook");refresh.setOnClickListener(v->request(null));page.addView(refresh);archiveButton=new Button(this);archiveButton.setText("Show archived history");archiveButton.setOnClickListener(v->{showArchive=!showArchive;archiveButton.setText(showArchive?"Hide archived history":"Show archived history");request(null);});page.addView(archiveButton,3);book=new TextView(this);book.setTextIsSelectable(true);page.addView(book,4);request(null);}
 void request(JSONObject data){if(loading)return;loading=true;state.setText("Connecting to VM…");io.execute(()->{HttpsURLConnection c=null;try{VoiceService service=VoiceService.instance;if(service==null)throw new IOException("Open Rose Agent first");c=(HttpsURLConnection)new URL(service.endpoint+"/conversation-mode").openConnection();c.setSSLSocketFactory(service.ssl);c.setHostnameVerifier((h,s)->true);c.setConnectTimeout(8000);c.setReadTimeout(75000);if(data!=null){c.setRequestMethod("POST");c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(data.toString().getBytes("UTF-8"));}}int code=c.getResponseCode();JSONObject result=new JSONObject(VoiceService.read(code<400?c.getInputStream():c.getErrorStream()));if(code>=400)throw new IOException(result.optString("error","Request failed"));runOnUiThread(()->{loading=false;if(isFinishing())return;JSONObject meeting=result.optJSONObject("meeting");state.setText(result.optBoolean("active")?"ACTIVE · notes only":"Inactive · normal task mode");if(meeting!=null){meetingId=meeting.optString("id");JSONObject work=meeting.optJSONObject("work");if(work!=null)state.append("\nWork: "+work.optString("status")+" "+work.optString("url"));if(data!=null||title.getText().length()==0){title.setText(meeting.optString("title"));notes.setText(meeting.optString("notes"));}StringBuilder content=new StringBuilder("ACTION ITEMS\n");JSONObject items=meeting.optJSONObject("actionItems");if(items!=null){java.util.Iterator<String> keys=items.keys();while(keys.hasNext()){String key=keys.next();JSONObject item=items.optJSONObject(key);if(item==null)continue;content.append("\n").append(key).append(" · ").append(item.optString("status")).append("\n").append(item.optString("summary")).append("\n").append(item.optString("evidence")).append("\n");}}content.append("\nRECENT NOTES\n");JSONArray entries=meeting.optJSONArray("notebook");if(entries!=null)for(int i=entries.length()-1;i>=0;i--){JSONObject entry=entries.optJSONObject(i);content.append("\n").append(entry.optString("at")).append("\n").append(entry.optString("text")).append("\n");}JSONArray archive=meeting.optJSONArray("archive");if(showArchive&&archive!=null&&archive.length()>0){content.append("\nARCHIVE ("+archive.length()+" entries)\n");for(int j=0;j<archive.length();j++)content.append("\n").append(archive.optJSONObject(j).optString("text")).append("\n");}book.setText(content.toString());}});}catch(Exception e){runOnUiThread(()->{loading=false;if(!isFinishing())state.setText("Could not update mode: "+e.getMessage());});}finally{if(c!=null)c.disconnect();}});}
 public void onDestroy(){io.shutdownNow();super.onDestroy();}
}
